CREATE TABLE IF NOT EXISTS t_knowledge_base(id BIGINT PRIMARY KEY AUTO_INCREMENT,base_code VARCHAR(64) UNIQUE,name VARCHAR(200),status VARCHAR(32) DEFAULT 'ACTIVE',created_time DATETIME DEFAULT CURRENT_TIMESTAMP);INSERT IGNORE INTO t_knowledge_base(id,base_code,name)VALUES(1,'KB_DEFAULT','默认知识库');
CREATE TABLE IF NOT EXISTS t_source(id BIGINT PRIMARY KEY AUTO_INCREMENT,source_code VARCHAR(64) UNIQUE,knowledge_base_id BIGINT NOT NULL,name VARCHAR(255),source_type VARCHAR(64),source_uri VARCHAR(1000),authority_score DECIMAL(6,4),status VARCHAR(32),created_time DATETIME DEFAULT CURRENT_TIMESTAMP,KEY idx_source_kb(knowledge_base_id));
CREATE TABLE IF NOT EXISTS t_source_version(id BIGINT PRIMARY KEY AUTO_INCREMENT,source_id BIGINT NOT NULL,version_no INT,source_hash VARCHAR(128),object_uri VARCHAR(1000),status VARCHAR(32),created_time DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_sv(source_id,version_no));
CREATE TABLE IF NOT EXISTS t_document(id BIGINT PRIMARY KEY AUTO_INCREMENT,source_version_id BIGINT NOT NULL,document_code VARCHAR(64) UNIQUE,title VARCHAR(500),mime_type VARCHAR(128),raw_text LONGTEXT,parse_status VARCHAR(32),chunk_count INT DEFAULT 0,created_time DATETIME DEFAULT CURRENT_TIMESTAMP,KEY idx_doc_sv(source_version_id));
CREATE TABLE IF NOT EXISTS t_content_unit(id BIGINT PRIMARY KEY AUTO_INCREMENT,document_id BIGINT NOT NULL,unit_code VARCHAR(64) UNIQUE,parent_id BIGINT,heading_path VARCHAR(1000),page_no INT,content LONGTEXT,content_hash VARCHAR(128),created_time DATETIME DEFAULT CURRENT_TIMESTAMP,KEY idx_cu_doc(document_id));
CREATE TABLE IF NOT EXISTS t_evidence(id BIGINT PRIMARY KEY AUTO_INCREMENT,evidence_code VARCHAR(64) UNIQUE,knowledge_base_id BIGINT NOT NULL,content_unit_id BIGINT,source_id BIGINT,quote_text TEXT,location_json JSON,authority_score DECIMAL(6,4),freshness_score DECIMAL(6,4),status VARCHAR(32),created_time DATETIME DEFAULT CURRENT_TIMESTAMP,KEY idx_ev_kb(knowledge_base_id));
CREATE TABLE IF NOT EXISTS t_entity(id BIGINT PRIMARY KEY AUTO_INCREMENT,entity_code VARCHAR(64) UNIQUE,knowledge_base_id BIGINT,entity_type VARCHAR(64),canonical_name VARCHAR(255),description TEXT,confidence DECIMAL(6,4),status VARCHAR(32),created_time DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS t_relation(id BIGINT PRIMARY KEY AUTO_INCREMENT,relation_code VARCHAR(64) UNIQUE,knowledge_base_id BIGINT,source_entity_id BIGINT,relation_type VARCHAR(64),target_entity_id BIGINT,confidence DECIMAL(6,4),status VARCHAR(32),created_time DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS t_claim(id BIGINT PRIMARY KEY AUTO_INCREMENT,claim_code VARCHAR(64) UNIQUE,knowledge_base_id BIGINT NOT NULL,subject VARCHAR(500),predicate VARCHAR(128),object_value TEXT,condition_json JSON,confidence DECIMAL(6,4),status VARCHAR(32),created_time DATETIME DEFAULT CURRENT_TIMESTAMP,updated_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_claim_kb_status(knowledge_base_id,status));
CREATE TABLE IF NOT EXISTS t_knowledge_card(id BIGINT PRIMARY KEY AUTO_INCREMENT,knowledge_code VARCHAR(64) UNIQUE,knowledge_base_id BIGINT NOT NULL,type VARCHAR(64),title VARCHAR(500),summary TEXT,content LONGTEXT,confidence DECIMAL(6,4),status VARCHAR(32),version INT DEFAULT 1,created_time DATETIME DEFAULT CURRENT_TIMESTAMP,updated_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,KEY idx_card_kb_status(knowledge_base_id,status));
CREATE TABLE IF NOT EXISTS t_knowledge_review(id BIGINT PRIMARY KEY AUTO_INCREMENT,object_type VARCHAR(32),object_code VARCHAR(64),decision VARCHAR(32),reviewer VARCHAR(128),comment_text TEXT,created_time DATETIME DEFAULT CURRENT_TIMESTAMP,KEY idx_review_object(object_type,object_code));
CREATE TABLE IF NOT EXISTS t_knowledge_conflict(id BIGINT PRIMARY KEY AUTO_INCREMENT,knowledge_base_id BIGINT,object_a_code VARCHAR(64),object_b_code VARCHAR(64),conflict_type VARCHAR(64),conflict_score DECIMAL(6,4),status VARCHAR(32),resolution TEXT,created_time DATETIME DEFAULT CURRENT_TIMESTAMP,updated_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uk_conflict_pair(knowledge_base_id,object_a_code,object_b_code,conflict_type),KEY idx_conflict_status(knowledge_base_id,status));
CREATE TABLE IF NOT EXISTS t_query_trace(id BIGINT PRIMARY KEY AUTO_INCREMENT,query_id VARCHAR(64) UNIQUE,knowledge_base_id BIGINT,original_query TEXT,trace_json JSON,answer LONGTEXT,created_time DATETIME DEFAULT CURRENT_TIMESTAMP,KEY idx_trace_kb_time(knowledge_base_id,created_time));

-- V1.1 智能裁决：知识对象与证据的可追溯关系
CREATE TABLE IF NOT EXISTS t_claim_evidence(
 id BIGINT PRIMARY KEY AUTO_INCREMENT,claim_code VARCHAR(80) NOT NULL,evidence_id BIGINT NOT NULL,
 support_type VARCHAR(32) DEFAULT 'SUPPORT',support_score DECIMAL(6,4) DEFAULT 0.8000,created_time DATETIME DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uk_claim_evidence(claim_code,evidence_id),KEY idx_ce_claim(claim_code));
CREATE TABLE IF NOT EXISTS t_knowledge_evidence(
 id BIGINT PRIMARY KEY AUTO_INCREMENT,knowledge_code VARCHAR(80) NOT NULL,evidence_id BIGINT NOT NULL,
 support_type VARCHAR(32) DEFAULT 'SUPPORT',support_score DECIMAL(6,4) DEFAULT 0.8000,created_time DATETIME DEFAULT CURRENT_TIMESTAMP,
 UNIQUE KEY uk_knowledge_evidence(knowledge_code,evidence_id),KEY idx_ke_knowledge(knowledge_code));
CREATE TABLE IF NOT EXISTS t_adjudication_assessment(
 id BIGINT PRIMARY KEY AUTO_INCREMENT,knowledge_base_id BIGINT NOT NULL,object_type VARCHAR(32) NOT NULL,object_code VARCHAR(80) NOT NULL,
 policy_version VARCHAR(64),knowledge_confidence DECIMAL(6,4),risk_level VARCHAR(32),decision VARCHAR(40),requires_human_review TINYINT(1) DEFAULT 1,
 score_json JSON,ai_judge_json JSON,reason_text TEXT,created_time DATETIME DEFAULT CURRENT_TIMESTAMP,
 KEY idx_assessment_object(object_type,object_code),KEY idx_assessment_kb(knowledge_base_id,created_time));
